	sections = {
		{
			title = "Summary",
			text = [=[Sentinel Hill rises in the middle of {link:westfall}Westfall{/link}, just off the great road. On its crown stands a stone watchtower, and around it a small village has gathered for safety: an inn, the stalls of the MacGregor family and the posts of the militia. This is the headquarters of the People's Militia. From the top of the tower {link:gryan-stoutmantle}Gryan Stoutmantle{/link} and his officers watch the plains and send out their scouts. It is the last place in Westfall where the law of {link:stormwind-city}Stormwind{/link} is still spoken aloud, though Stormwind itself sends nothing to enforce it.]=],
		},
	},
})

