Add({
	kind = "topic",
	id = "harvest-golems",
	title = "Harvest Golems",
	aliases = { "harvest golems", "Harvest Golem", "harvest golem", "Harvest Watchers", "Harvest Watcher", "harvest machines" },
	category = "mechanism",
	region = "westfall",
	npc = { 36, 480, 114, 115, 573 },
	unlock = {
		{ type = "target" },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Harvest golems are great machines of iron built to work the fields of {link:westfall}Westfall{/link}. They were made to reap, to sow and to watch over the crops. Now they walk the abandoned farms with no master and drive off anyone who comes near, as though the farmers themselves were pests to be cleared from the rows.]=],
		},
		{
			title = "Kinds",
			text = [=[• {b}Rusty harvest golems{/b} and {b}harvest golems{/b} are the smallest and weakest of them.
• {b}Harvest Watchers{/b} stand guard over the fields, as their name suggests.
• {b}Harvest Reapers{/b} are the largest and most dangerous. They roam the burned fields of the {link:the-dead-acre}Dead Acre{/link}.
• {b}The Foe Reaper 4000{/b} is a single machine, far stronger than the rest, that roams the fields of the western plains.]=],
		},
		{
			title = "In These Days",
			text = [=[No farmer can say for certain how the machines went wrong. Many in {link:westfall}Westfall{/link} blame the {link:defias-brotherhood}Defias Brotherhood{/link}, whose goblin allies build and command golems in the depths of the {link:the-deadmines}Deadmines{/link}. The {link:gnomes}gnome{/link} {link:ozwin-ironsprocket}Ozwin Ironsprocket{/link} has studied their parts and learned how to override them, though only for a moment. The ghost of the {link:westfall-lighthouse}Westfall Lighthouse{/link} feeds his flame with oil drained from their joints. {link:farmer-saldean}Farmer Saldean{/link} simply wants them gone.]=],
		},
	},
})
